shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

    :host {
      --paper: #faf8f4;
      --paper-card: #f3efe6;
      --paper-elevated: #ece6d8;
      --ink: #141413;
      --body: #242220;
      --muted: #646059;
      --line: #e4dfd3;
      --line-strong: #c8c0b0;
      --accent: #b85d19;
      --accent-soft: rgba(184, 93, 25, 0.12);
      --navy-bg: #0f1d2b;
      --navy-card: #16283a;
      --navy-line: #294057;
      --gold: #d49b4b;
      --teal: #1d6b63;
      --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
      --font-serif-cn: 'Noto Serif SC', 'Lora', Georgia, serif;
      --font-serif-en: 'Lora', 'Noto Serif SC', Georgia, serif;
      --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
      --font-mono: 'JetBrains Mono', monospace;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      background-color: var(--paper);
      color: var(--body);
      scroll-behavior: smooth;
      -webkit-font-smoothing: antialiased;
    }

    .wsj-shadow-body {
      font-family: var(--font-serif-cn);
      background-color: var(--paper);
      color: var(--body);
      line-height: 1.85;
      overflow-x: hidden;
    }

    :host([lang="en"]) .wsj-shadow-body {
      font-family: var(--font-serif-en);
      line-height: 1.78;
    }

    /* Strictly enforced bilingual toggle rules */
    :host([lang="zh-CN"]) .lang-en { display: none !important; }
    :host([lang="en"]) .lang-cn { display: none !important; }

    /* Highlight mark styling */
    mark.ed-hl {
      background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(212, 155, 75, 0.24) 100%);
      color: var(--ink);
      padding: 0.08em 0.28em;
      border-radius: 2px;
      border-bottom: 1.5px solid var(--accent);
      font-weight: 600;
    }

    /* Sticky Top Masthead */
    .wsj-masthead {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: rgba(250, 248, 244, 0.94);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--line-strong);
    }

    .masthead-inner {
      max-width: 1180px;
      margin: 0 auto;
      padding: 0.7rem 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand-cluster {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      min-width: 0;
    }

    .wsj-monogram {
      font-family: var(--font-display);
      font-weight: 800;
      font-size: 1.25rem;
      letter-spacing: 0.06em;
      color: var(--ink);
      border-right: 1px solid var(--line-strong);
      padding-right: 0.85rem;
      white-space: nowrap;
    }

    .section-pill {
      font-family: var(--font-sans);
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--accent);
      white-space: nowrap;
    }

    .masthead-controls {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .edition-tag {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--muted);
      letter-spacing: 0.04em;
    }

    .lang-switch {
      display: inline-flex;
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      border-radius: 999px;
      padding: 2px;
    }

    .lang-btn {
      appearance: none;
      border: none;
      background: transparent;
      font-family: var(--font-sans);
      font-size: 0.74rem;
      font-weight: 600;
      padding: 0.28rem 0.72rem;
      border-radius: 999px;
      color: var(--muted);
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .lang-btn.active {
      background: var(--ink);
      color: var(--paper);
    }

    /* Reading Progress Bar */
    .progress-bar {
      height: 2px;
      background: var(--accent);
      width: 0%;
      transition: width 0.1s linear;
    }

    /* Hero Header */
    .hero-wrapper {
      max-width: 1180px;
      margin: 0 auto;
      padding: 3.2rem 1.5rem 2.2rem;
      border-bottom: 1px solid var(--line);
    }

    .kicker-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.65rem;
      margin-bottom: 1.15rem;
      font-family: var(--font-sans);
    }

    .kicker-badge {
      background: var(--ink);
      color: var(--paper);
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      padding: 0.24rem 0.6rem;
    }

    .kicker-sub {
      font-family: var(--font-mono);
      font-size: 0.76rem;
      color: var(--accent);
      font-weight: 600;
      letter-spacing: 0.05em;
    }

    .headline {
      font-family: var(--font-display);
      font-size: clamp(2.1rem, 4.3vw, 3.55rem);
      font-weight: 800;
      line-height: 1.18;
      color: var(--ink);
      letter-spacing: -0.015em;
      margin-bottom: 1.25rem;
      max-width: 24ch;
    }

    :host([lang="zh-CN"]) .headline {
      max-width: 19ch;
      line-height: 1.26;
    }

    .hero-deck {
      font-size: clamp(1.06rem, 1.6vw, 1.26rem);
      color: var(--muted);
      max-width: 74ch;
      line-height: 1.68;
      margin-bottom: 1.75rem;
      font-weight: 400;
    }

    .byline-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1.15rem;
      border-top: 1px solid var(--line);
      font-family: var(--font-sans);
      font-size: 0.84rem;
      color: var(--muted);
    }

    .byline-authors strong {
      color: var(--ink);
      font-weight: 600;
    }

    .byline-meta {
      font-family: var(--font-mono);
      font-size: 0.78rem;
      color: var(--muted);
    }

    /* Deal Snapshot Strip (Verified Metrics m1..m3) */
    .metrics-strip-section {
      max-width: 1180px;
      margin: 0 auto;
      padding: 1.8rem 1.5rem;
      border-bottom: 1px solid var(--line);
    }

    .strip-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 1rem;
      font-family: var(--font-sans);
    }

    .strip-title {
      font-size: 0.76rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      color: var(--muted);
    }

    .strip-source {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--muted);
    }

    .metrics-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.2rem;
    }

    .metric-card {
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      border-top: 3px solid var(--accent);
      padding: 1.25rem 1.35rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .metric-card[data-derive="m2"] {
      border-top-color: var(--teal);
    }

    .metric-card[data-derive="m3"] {
      border-top-color: var(--navy-bg);
    }

    .metric-val {
      font-family: var(--font-mono);
      font-size: clamp(1.65rem, 2.5vw, 2.25rem);
      font-weight: 700;
      color: var(--ink);
      line-height: 1.15;
      margin-bottom: 0.4rem;
    }

    .metric-lbl {
      font-family: var(--font-sans);
      font-size: 0.85rem;
      font-weight: 700;
      color: var(--ink);
      margin-bottom: 0.45rem;
    }

    .metric-note {
      font-family: var(--font-sans);
      font-size: 0.78rem;
      color: var(--muted);
      line-height: 1.5;
    }

    /* Main Editorial Layout: Asymmetric Two-Column Forensic Rail */
    .editorial-stage {
      max-width: 1180px;
      margin: 0 auto;
      padding: 2.6rem 1.5rem 4rem;
      display: grid;
      grid-template-columns: minmax(0, 1.65fr) minmax(290px, 1fr);
      gap: 3.2rem;
      align-items: start;
    }

    .narrative-column {
      min-width: 0;
    }

    .dossier-rail {
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: 1.8rem;
      position: sticky;
      top: 4.5rem;
    }

    /* Prose Styling */
    .prose-p {
      font-size: 1.125rem;
      color: var(--body);
      margin-bottom: 1.55rem;
      letter-spacing: 0.01em;
    }

    /* Lead paragraph treatment without CSS ::first-letter on Chinese */
    .prose-lead {
      font-size: 1.26rem;
      line-height: 1.82;
      color: var(--ink);
      font-weight: 600;
      padding-left: 1.15rem;
      border-left: 3.5px solid var(--accent);
      margin-bottom: 1.85rem;
    }

    /* Chapter Divider inside article */
    .section-divider {
      margin: 2.3rem 0 1.5rem;
      padding-top: 1.4rem;
      border-top: 1px solid var(--line-strong);
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }

    .divider-num {
      font-family: var(--font-mono);
      font-size: 0.75rem;
      font-weight: 700;
      color: var(--paper);
      background: var(--ink);
      padding: 0.18rem 0.5rem;
    }

    .divider-label {
      font-family: var(--font-sans);
      font-size: 0.82rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--accent);
    }

    /* Bespoke Inline Analytical SVG Containers */
    .graphic-card {
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      padding: 1.5rem;
      margin: 2.1rem 0;
    }

    .graphic-kicker {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--accent);
      margin-bottom: 0.35rem;
      font-weight: 700;
    }

    .graphic-title {
      font-family: var(--font-display);
      font-size: 1.28rem;
      font-weight: 700;
      color: var(--ink);
      margin-bottom: 0.4rem;
      line-height: 1.3;
    }

    .graphic-subtitle {
      font-family: var(--font-sans);
      font-size: 0.84rem;
      color: var(--muted);
      margin-bottom: 1.2rem;
      line-height: 1.5;
    }

    .svg-wrap {
      width: 100%;
      overflow: hidden;
      background: var(--paper);
      border: 1px solid var(--line);
      padding: 0.5rem;
    }

    .graphic-footnote {
      margin-top: 0.8rem;
      font-family: var(--font-sans);
      font-size: 0.75rem;
      color: var(--muted);
      display: flex;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    /* Right Rail Dossier Cards */
    .navy-dossier {
      background: var(--navy-bg);
      color: #f2efe9;
      padding: 1.6rem;
      border-top: 4px solid var(--gold);
      box-shadow: 0 10px 28px rgba(15, 29, 43, 0.12);
    }

    .dossier-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 1px solid var(--navy-line);
      padding-bottom: 0.8rem;
      margin-bottom: 1.1rem;
    }

    .dossier-tag {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--gold);
      font-weight: 700;
    }

    .dossier-stamp {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      color: #9ab0c7;
      border: 1px solid var(--navy-line);
      padding: 0.12rem 0.45rem;
    }

    .dossier-title {
      font-family: var(--font-display);
      font-size: 1.2rem;
      color: #ffffff;
      margin-bottom: 0.9rem;
      line-height: 1.35;
    }

    .dossier-ctx-body {
      font-family: var(--font-sans);
      font-size: 0.88rem;
      line-height: 1.72;
      color: #d7e1ec;
      margin-bottom: 1.25rem;
    }

    .entity-table {
      width: 100%;
      border-collapse: collapse;
      font-family: var(--font-sans);
      font-size: 0.8rem;
    }

    .entity-table tr {
      border-top: 1px solid var(--navy-line);
    }

    .entity-table th {
      text-align: left;
      padding: 0.55rem 0.4rem 0.55rem 0;
      color: #9ab0c7;
      font-weight: 500;
      width: 38%;
      vertical-align: top;
    }

    .entity-table td {
      padding: 0.55rem 0;
      color: #ffffff;
      font-weight: 600;
    }

    /* Silicon Architecture Card in Rail */
    .tech-brief-card {
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      padding: 1.45rem;
    }

    .tech-brief-card h3 {
      font-family: var(--font-display);
      font-size: 1.1rem;
      color: var(--ink);
      margin-bottom: 0.5rem;
    }

    .tech-brief-card p {
      font-family: var(--font-sans);
      font-size: 0.83rem;
      color: var(--muted);
      line-height: 1.6;
      margin-bottom: 1rem;
    }

    /* Footer */
    .wsj-footer {
      border-top: 2px solid var(--ink);
      background: var(--paper-card);
      padding: 2.5rem 1.5rem;
      font-family: var(--font-sans);
      font-size: 0.8rem;
      color: var(--muted);
    }

    .footer-inner {
      max-width: 1180px;
      margin: 0 auto;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
    }

    /* Responsive Mobile Reflow (390px and below) */
    @media (max-width: 920px) {
      .editorial-stage {
        grid-template-columns: 1fr;
        gap: 2.2rem;
      }
      .dossier-rail {
        position: static;
      }
      .metrics-grid {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      .masthead-inner {
        padding: 0.6rem 1rem;
      }
      .edition-tag {
        display: none;
      }
      .hero-wrapper,
      .metrics-strip-section,
      .editorial-stage {
        padding-left: 1rem;
        padding-right: 1rem;
      }
      .headline {
        font-size: 1.85rem;
      }
      .prose-lead {
        font-size: 1.12rem;
        padding-left: 0.85rem;
      }
      .prose-p {
        font-size: 1.04rem;
      }
      .graphic-card {
        padding: 1rem;
      }
    }
